# Decode ``~1`` first: decoding ``~0`` first would turn ``~01`` into
# ``~1`` and then incorrectly decode it as a slash.
return token.replace("~1", "/").replace("~0", "~")

def test_escaped_keys(self):
    doc = {"~1": "tilde-one", "a/b": "slash"}
    self.assertEqual(resolve(doc, "/~01"), "tilde-one")
    self.assertEqual(resolve(doc, "/a~1b"), "slash")

def test_missing_and_malformed(self):
    with self.assertRaises(KeyError):
        resolve(DOC, "/users/5")
    with self.assertRaises(ValueError):
        resolve(DOC, "users")
